import json
from collections import deque

T = [[1, 2, 3, 0], [1, 0, 2, 3]]
U = [[3, 2, 0, 1], [2, 1, 0, 3]]
d = 4
V = d + 5
F = [None] * d
conflict = False
mode = 'idle'
reg = 0
assignments = 0


def close(i, j):
    global conflict, assignments
    if conflict:
        return
    queue = deque([(i, j)])
    while queue and not conflict:
        x, y = queue.popleft()
        if F[x] is None:
            F[x] = y
            assignments += 1
            for a in range(2):
                queue.append((T[a][x], U[a][y]))
        elif F[x] != y:
            conflict = True
            queue.clear()


def feed(token):
    global mode, reg
    numeric = isinstance(token, int) and 0 <= token < d
    if mode == 'idle':
        if token == 'D':
            mode = 'demo_source'
        elif token == 'Q':
            mode = 'query_source'
    elif mode == 'demo_source' and numeric:
        reg = token
        mode = 'demo_target'
    elif mode == 'demo_target' and numeric:
        close(reg, token)
        mode = 'idle'
    elif mode == 'query_source' and numeric:
        reg = token
        mode = 'word'
    elif mode == 'word' and token in ('L', 'R'):
        reg = T[0 if token == 'L' else 1][reg]
    elif mode == 'word' and token == '?':
        mode = 'answer'
    elif mode == 'answer' and numeric:
        mode = 'idle'
    else:
        mode = 'idle'
    if mode != 'answer':
        return [1.0 / V] * V
    if conflict or F[reg] is None:
        return [1.0 / d] * d + [0.0] * 5
    p = [0.0] * V
    p[F[reg]] = 1.0
    return p


for token in ['D', 0, 2]:
    feed(token)
learned = list(F)
answers = []
for word in [('L', 'R'), ('R', 'L')]:
    feed('Q')
    feed(0)
    for operation in word:
        feed(operation)
    p = feed('?')
    answer = p.index(1.0)
    answers.append(answer)
    feed(answer)
for token in ['D', 2, 0]:
    feed(token)
for token in ['Q', 1, '?']:
    p = feed(token)
result = {'learned_map': learned, 'assignments': assignments, 'LR_answer': answers[0], 'RL_answer': answers[1], 'conflict': conflict, 'fallback_distribution': [round(x, 4) for x in p]}
print(json.dumps(result, sort_keys=True))

import json
import numpy as np

ALPHA, BETA = 2.0, 2.0

class Learner:
    def __init__(self, d):
        self.d = d
        self.E = np.zeros((d, d))
        self.K = int(np.ceil(np.log2(d))) + 2
        self.M = 1.0 - np.eye(d)
    def demo(self, a, b, s):
        if a != b:
            sig = 1.0 - 2.0 * s
            self.E[a, b] += sig
            self.E[b, a] += sig
    def solve(self):
        H = np.zeros((self.d, self.d))
        for _ in range(self.K):
            H = self.M * np.tanh(ALPHA * self.E + BETA * (self.M * (H @ H)))
        return H
    def p_one(self, a, b):
        if a == b:
            return 0.0
        return float((1.0 - self.solve()[a, b]) / 2.0)

r = Learner(5)
for ev in [(0, 1, 1), (1, 2, 0), (2, 3, 1)]:
    r.demo(*ev)
ps = [r.p_one(a, b) for (a, b) in [(0, 2), (0, 3), (1, 3), (0, 4)]]
pred = [1 if p > 0.5 else (0 if p < 0.5 else None) for p in ps]
A = Learner(5)
B = Learner(5)
for ev in [(0, 1, 0), (1, 2, 0)]:
    A.demo(*ev)
    B.demo(*ev)
B.demo(0, 2, 0)
rises = bool(B.solve()[0, 2] > A.solve()[0, 2])
N = Learner(5)
for s in [0, 0, 0, 1, 1]:
    N.demo(0, 1, s)
T = Learner(5)
T.demo(0, 1, 0)
T.demo(0, 1, 1)
result = {'pred': pred, 'p_one_disconnected': round(ps[3], 3), 'confidence_rises_with_redundant_path': rises, 'p_one_noisy_majority': round(N.p_one(0, 1), 3), 'p_one_tie': round(T.p_one(0, 1), 3)}
print(json.dumps(result, sort_keys=True))

import json
def mul(P,Q):
    return [[P[0][0]*Q[0][0]+P[0][1]*Q[1][0],P[0][0]*Q[0][1]+P[0][1]*Q[1][1]],[P[1][0]*Q[0][0]+P[1][1]*Q[1][0],P[1][0]*Q[0][1]+P[1][1]*Q[1][1]]]
def C(j):
    return [[1+j,j],[1,1]]
def adj(M):
    return [[M[1][1],-M[0][1]],[-M[1][0],M[0][0]]]
RES={'<','?','yes','no'}
M={'ROOT':[[1,0],[0,1]]}
K={'ROOT':0}
par={}
rej=0
def attach(x,y):
    j=K[y]; K[y]=j+1; M[x]=mul(M[y],C(j)); K[x]=0; par[x]=y
stream='mammal < animal bird < animal dog < mammal cat < mammal robin < bird animal < life'.split()
for t in range(2,len(stream)):
    X,op,Y=stream[t-2],stream[t-1],stream[t]
    if op!='<' or X in RES or Y in RES:
        continue
    if X in M or X==Y:
        rej+=1
        continue
    if Y not in M: attach(Y,'ROOT')
    attach(X,Y)
def desc(x,y):
    R=mul(adj(M[y]),M[x])
    return int(min(R[0]+R[1])>=0)
def truth(x,y):
    while True:
        if x==y: return 1
        if x=='ROOT': return 0
        x=par[x]
queries=[('dog','animal'),('robin','animal'),('robin','mammal'),('cat','bird'),('animal','dog'),('dog','cat'),('cat','mammal')]
ans=[desc(x,y) for x,y in queries]
tru=[truth(x,y) for x,y in queries]
acc=round(sum(int(a==b) for a,b in zip(ans,tru))/len(queries),3)
print(json.dumps({"answers":ans,"truth":tru,"accuracy":acc,"rejected":rej,"life_known":'life' in M,"M_robin":M['robin'],"M_cat":M['cat']}))

update.plain:
For three distinct point labels u_1, u_2 and u_3, build the frame matrix M from the bracket products shown. Row 0 is (ca*e(u_2)_1, -ca*e(u_2)_0), where ca = [e(u_3),e(u_1)]. Row 1 is (cb*e(u_1)_1, -cb*e(u_1)_0), where cb = [e(u_3),e(u_2)]. M sends u_1 to infinity, u_2 to 0 and u_3 to 1.

With three anchors:
- build the input frame M(alpha_1,alpha_2,alpha_3) from the input labels of A;
- build the output frame M(beta_1,beta_2,beta_3) from the output labels;
- multiply the inverse of the output frame by the input frame;
- apply the product to e(z) and decode the result to a token.

T_A is evaluated only when r = 3.

toy_example.python:
import json

p = 5
V = p + 1
anchors = []
rejected = False

def point(z):
    return (1, 0) if z == p else (z, 1)

def bracket(u, v):
    return (u[0] * v[1] - u[1] * v[0]) % p

def decode(u):
    return p if u[1] % p == 0 else (u[0] * pow(u[1] % p, -1, p)) % p

def frame(a, b, c):
    a, b, c = point(a), point(b), point(c)
    ca = bracket(c, a)
    cb = bracket(c, b)
    return [[ca * b[1] % p, -ca * b[0] % p],
            [cb * a[1] % p, -cb * a[0] % p]]

def inverse(M):
    a, b = M[0]
    c, d = M[1]
    s = pow((a * d - b * c) % p, -1, p)
    return [[d * s % p, -b * s % p],
            [-c * s % p, a * s % p]]

def multiply(A, B):
    return [[sum(A[i][k] * B[k][j] for k in range(2)) % p
             for j in range(2)] for i in range(2)]

def apply(M, z):
    u = point(z)
    return decode(tuple(sum(M[i][j] * u[j] for j in range(2)) % p
                        for i in range(2)))

def reconstructed():
    xs = [a for a, b in anchors]
    ys = [b for a, b in anchors]
    return multiply(inverse(frame(*ys)), frame(*xs))

def observe(x, y):
    global rejected
    if rejected:
        return
    if len(anchors) == 3:
        rejected = apply(reconstructed(), x) != y
        return
    for a, b in anchors:
        if x == a:
            rejected = y != b
            return
    if y in [b for a, b in anchors]:
        rejected = True
    else:
        anchors.append((x, y))

def predict(x):
    if rejected:
        return [1.0 / V] * V
    if len(anchors) == 3:
        y = apply(reconstructed(), x)
        return [float(v == y) for v in range(V)]
    for a, b in anchors:
        if x == a:
            return [float(v == b) for v in range(V)]
    used = {b for a, b in anchors}
    return [0.0 if v in used else 1.0 / (V - len(anchors))
            for v in range(V)]

def select():
    used_inputs = {a for a, b in anchors}
    return min(z for z in range(4) if z not in used_inputs)

hidden = [[2, 1], [1, 1]]
queries = []
for step in range(2):
    x = select()
    queries.append(x)
    observe(x, apply(hidden, x))
x = select()
before_third = [round(v, 6) for v in predict(x)]
queries.append(x)
observe(x, apply(hidden, x))
mapping = [max(range(V), key=lambda y: predict(x)[y]) for x in range(V)]
observe(3, 4)
result = {'queries': queries, 'before_third': before_third,
          'mapping': mapping, 'rejected': rejected,
          'fallback': [round(v, 6) for v in predict(3)]}
print(json.dumps(result, sort_keys=True))

equations.plain:
q_t = softmax(P @ u_t / gamma0). For each earlier position r in the window max(0, t-Omega)..t-1:
- a = 1 if norm(rho_t - rho_r) <= tau else 0, where rho_t and rho_r are the episode residuals at positions t and r;
- o = dot(q_t, q_r)/gamma - eta;
- Lcode_t -= a*log(sigmoid(o)) + (1-a)*log(1-sigmoid(o)).
Here gamma0 and gamma are temperatures, eta is a fixed scalar offset, Omega is the window length and lambda is the loss weight.

