import json, math
import numpy as np
L3=math.log(3.0)
DELTA=1.0; LAM=0.5
def pt(R,th):
    s=math.tanh(R/2)
    return np.array([s*math.cos(th),s*math.sin(th)])
def ang(R1,R2,q):
    d=R1+R2-2*q
    return math.acos((math.cosh(R1)*math.cosh(R2)-math.cosh(d))/(math.sinh(R1)*math.sinh(R2)))
E={'dalmatian':pt(2*L3,0.0),'poodle':pt(2*L3,ang(2*L3,2*L3,L3)),'terrier':pt(2*L3,-ang(2*L3,2*L3,L3)),'beagle':pt(3*L3,ang(2*L3,3*L3,L3)),'cat':pt(2*L3,math.pi)}
EXACT={'dalmatian':2*L3,'poodle':L3,'terrier':L3,'beagle':L3,'cat':0.0}
def rho(x):
    return 2*math.atanh(math.sqrt(float(x@x)))
def dist(x,y):
    nx=float(x@x); ny=float(y@y); dd=float((x-y)@(x-y))
    return math.acosh(1+2*dd/((1-nx)*(1-ny)))
def G(x,y):
    return (rho(x)+rho(y)-dist(x,y))/2
def prob(st,y):
    a,g,h,k=st
    z=G(E[y],E[a]); c=DELTA*k-LAM
    if g<=h:
        P=1.0 if z>=g else 0.0
    else:
        m=max(h,min(z,g))
        if abs(c)<1e-12:
            P=(m-h)/(g-h)
        else:
            P=(math.exp(c*m)-math.exp(c*h))/(math.exp(c*g)-math.exp(c*h))
    return round(min(1.0,max(0.0,P)),3)
W={'dax','fep','wug'}; OPS={'+','-','?'}
stream='dax + dalmatian dax ? poodle dax ? cat dax + dalmatian dax + dalmatian dax ? poodle fep + dalmatian fep + poodle fep + terrier fep ? beagle fep ? cat wug + dalmatian wug - poodle wug ? dalmatian wug ? beagle'
toks=['BOS','BOS']+stream.split()
T={}; out=[]
for t in range(2,len(toks)):
    w,op,x=toks[t-2],toks[t-1],toks[t]
    if w not in W or op not in OPS or x not in E:
        continue
    if op=='+':
        if w not in T:
            T[w]=[x,G(E[x],E[x]),0.0,1]
        else:
            T[w][1]=min(T[w][1],G(E[x],E[T[w][0]])); T[w][3]+=1
    elif op=='-':
        if w in T:
            T[w][2]=max(T[w][2],G(E[x],E[T[w][0]]))
    else:
        out.append(prob(T[w],x) if w in T else 0.5)
gerr=max(abs(G(E[y],E['dalmatian'])-EXACT[y]) for y in E)
print(json.dumps({'P':out,'g_fep':round(T['fep'][1],3),'h_wug':round(T['wug'][2],3),'k_dax':T['dax'][3],'G_exact_ok':bool(gerr<1e-9)}))
